import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val s = br.readLine()
    val n = s.length
    val seen = HashSet<String>()

    var current = s
    for (i in 0 until n) {
        seen.add(current)
        // cyclic shift: move last char to front
        current = current.last() + current.substring(0, n - 1)
    }

    println(seen.size)
}

