import java.util.*

fun main() {
    val s = readLine() ?: return
    val n = s.length
    val seen = HashSet<String>()
    var cur = s
    repeat(n) {
        if (!seen.contains(cur)) {
            seen.add(cur)
        }
        cur = cur.last() + cur.substring(0, n - 1)
    }
    println(seen.size)
}

